mapper.select:
SELECT enterapply.hfpay_enterapply_id AS hfpay_enterapply_id, enterapply.distributor_id AS distributor_id, enterapply.status AS status, distributor.name AS name FROM hfpay_enterapply enterapply LEFT JOIN distribution_distributor distributor ON enterapply.distributor_id = distributor.distributor_id
ORDER BY enterapply.hfpay_enterapply_id DESC
LIMIT #{filter.limit} OFFSET #{filter.offset}

SELECT COUNT(*)
FROM hfpay_enterapply e
WHERE e.company_id = #{companyId}
AND e.apply_type IN ('1', '2')
AND e.status = '3'

	AND e.distributor_id = #{distributorId}

SELECT e.company_id AS company_id, e.distributor_id AS distributor_id, distributor.name AS distributor_name FROM hfpay_enterapply e LEFT JOIN distribution_distributor distributor ON e.distributor_id = distributor.distributor_id WHERE e.company_id = #{companyId} AND e.apply_type IN ('1', '2') AND e.status = '3'
AND e.distributor_id = #{distributorId}
LIMIT #{pageSize} OFFSET #{offset}
